// Initialize global context for water pump state
if (!global.get('water_pump_state')) {
    global.set('water_pump_state', {
        pump_power: 'UNKNOWN',
        drain_water: 'UNKNOWN',
        feed_trench_1: 'UNKNOWN',
        feed_trench_2: 'UNKNOWN',
        lastUpdate: new Date().toISOString()
    });
    node.warn('Initialized water_pump_state in global context');
} else {
    node.warn('water_pump_state already exists in global context');
}

return null;
